import { Bot, User } from "lucide-react";
import ReactMarkdown from "react-markdown";
import FeedbackCard from "./FeedbackCard";

export default function ChatWindow({
  activeChat,
  chatEndRef,
  pendingFeedback,
  onAcceptFeedback,
  onRejectFeedback,
  feedbackDisabled,
}) {
  return (
    <div className="chat">
      {activeChat?.messages.map((msg, index) => {
  const isLastMessage = index === activeChat.messages.length - 1;

  return (
    <div
      key={index}
      className={`message-row ${msg.sender === "user" ? "row-user" : "row-bot"}`}
    >
      {msg.sender === "bot" && (
        <div className="avatar avatar-bot">
          <Bot size={16} />
        </div>
      )}

      <div>
        <div
          className={`message ${
            msg.sender === "user" ? "message-user" : "message-bot"
          }`}
        >
          {/* message text */}

          <span className="msg-time">{msg.time}</span>
        </div>

        {msg.sender === "bot" && isLastMessage && pendingFeedback && (
          <FeedbackCard
            onAccept={onAcceptFeedback}
            onReject={onRejectFeedback}
            disabled={feedbackDisabled}
          />
        )}
      </div>

      {msg.sender === "user" && (
        <div className="avatar avatar-user">
          <User size={16} />
        </div>
      )}
    </div>
  );
})}
      
      {pendingFeedback && (
        <FeedbackCard
          onAccept={onAcceptFeedback}
          onReject={onRejectFeedback}
          disabled={feedbackDisabled}
        />
      )}
      <div ref={chatEndRef} />
    </div>
  );
}
